158	        currentOwner.setCity(ownerFieldsDto.getCity());
159	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
160	        currentOwner.setLastName(ownerFieldsDto.getLastName());
161	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
162	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
163	        this.clinicService.saveOwner(currentOwner);
164	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
165	    }
