232	    @Override
233	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
234	        Owner owner = this.clinicService.findOwnerById(ownerId);
235	        if (owner != null) {
236	            Pet pet = owner.getPet(petId);
237	            if (pet != null) {
238	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
239	            }
240	        }
241	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
242	    }
243	
244	    /**
245	     * Builds the customer code for a newly created owner, formatted {@code '<LAST3>-<NNNN>'} where
246	     * {@code LAST3} is the upper-cased first three letters of the owner's last name and {@code NNNN}
247	     * is a global 4-digit zero-padded sequence equal to one more than the current number of owners.
248	     * For example an owner named "Smithers" created when 10 owners already exist gets {@code 'SMI-0011'}.
249	     *
250	     * @param lastName the owner's last name
251	     * @return the assigned customer code
252	     */
253	    private String nextCustomerCode(String lastName) {
254	        String letters = lastName == null ? "" : lastName;
255	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
256	        int sequence = this.clinicService.findAllOwners().size() + 1;
257	        return String.format("%s-%04d", last3, sequence);
258	    }
259	
260	    /**
261	     * Rejects an owner payload that is missing or blank in any of the required fields
262	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
263	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
264	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
265	     * guard enforces the rule uniformly for every required field.
266	     *
267	     * @param ownerFieldsDto the submitted owner payload
268	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
269	     */
270	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
271	        List<String> invalidFields = new ArrayList<>();
272	        if (isBlank(ownerFieldsDto.getFirstName())) {
273	            invalidFields.add("firstName");
274	        }
275	        if (isBlank(ownerFieldsDto.getLastName())) {
276	            invalidFields.add("lastName");
277	        }
278	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
279	            invalidFields.add("address");
280	        }
281	        if (isBlank(ownerFieldsDto.getCity())) {
282	            invalidFields.add("city");
283	        }
284	        if (isBlank(ownerFieldsDto.getTelephone())) {
285	            invalidFields.add("telephone");
286	        }
287	        if (!invalidFields.isEmpty()) {
288	            throw new InvalidOwnerFieldsException(invalidFields);
289	        }
290	    }
291	
292	    private boolean isBlank(String value) {
293	        return value == null || value.isBlank();
294	    }
295	
296	    /**
297	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets are stripped.
298	     * A leading {@code '+'} and its country code are kept as-is; otherwise the country code {@code '+61'}
299	     * is assumed and a single leading {@code '0'} is dropped from the national digits. The result must be
300	     * a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} normalizes to
301	     * {@code "+61412345678"}. The E.164 string is what gets stored and returned.
302	     *
303	     * @param telephone the raw telephone value from the submitted owner payload
304	     * @return the normalized E.164 telephone number
305	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
306	     */
307	    private String normalizeTelephone(String telephone) {
308	        String raw = telephone == null ? "" : telephone.strip();
309	        boolean hasCountryCode = raw.startsWith("+");
310	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
311	        String digits;
312	        if (hasCountryCode) {
313	            digits = cleaned.substring(1);
314	        } else {
315	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
316	            digits = "61" + national;
317	        }
318	        if (!digits.matches("[0-9]{8,15}")) {
319	            throw new InvalidOwnerFieldsException(List.of("telephone"));
320	        }
321	        return "+" + digits;
322	    }
323	
324	    /**
325	     * Best-effort conversion of an existing telephone value to E.164 form for duplicate comparison,
326	     * returning {@code null} when the value cannot form a valid E.164 number.
327	     *
328	     * @param telephone an existing owner's stored telephone value
329	     * @return the E.164 form, or {@code null} if it cannot be normalized
330	     */
331	    private String toE164OrNull(String telephone) {
332	        try {
333	            return normalizeTelephone(telephone);
334	        } catch (InvalidOwnerFieldsException ex) {
335	            return null;
336	        }
337	    }
338	
339	    /**
340	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
341	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
342	     * accepted value is trimmed and lower-cased before it is stored and returned.
343	     *
344	     * @param email the raw email value from the submitted owner payload, may be {@code null}
345	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
346	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address
347	     */
348	    private String normalizeEmail(String email) {
349	        if (email == null) {
350	            return null;
351	        }
352	        String trimmed = email.strip();
353	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
354	            throw new InvalidOwnerFieldsException(List.of("email"));
355	        }
356	        return trimmed.toLowerCase(Locale.ROOT);
357	    }
358	
359	    /**
360	     * Rejects creating an owner whose E.164 telephone is already used by any other owner.
361	     * Existing owners' telephones are converted to E.164 form before comparison so that
362	     * differently-formatted representations of the same number are treated as duplicates.
363	     *
364	     * @param normalizedTelephone the E.164 telephone of the owner being created
365	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same E.164 telephone
366	     */
367	    private void rejectDuplicateTelephone(String normalizedTelephone) {
368	        boolean duplicate = this.clinicService.findAllOwners().stream()
369	            .map(Owner::getTelephone)
370	            .filter(telephone -> telephone != null)
371	            .map(this::toE164OrNull)
372	            .filter(telephone -> telephone != null)
373	            .anyMatch(normalizedTelephone::equals);
374	        if (duplicate) {
375	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
376	        }
377	    }
378	
379	    /**
380	     * Rejects creating an owner whose last name and address both match an existing owner. Both fields
381	     * are compared case-insensitively with surrounding and repeated internal whitespace collapsed, so
382	     * that e.g. {@code "  110  W. Liberty  St. "} and {@code "110 w. liberty st."} are treated as the
383	     * same address. This guard is bypassed for a request that sets {@code sharesHousehold} true.
384	     *
385	     * @param lastName the last name of the owner being created
386	     * @param address the address of the owner being created
387	     * @throws DuplicateOwnerHouseholdException if another owner shares the same last name and address
388	     */
389	    private void rejectDuplicateHousehold(String lastName, String address) {
390	        String normalizedLastName = normalizeForComparison(lastName);
391	        String normalizedAddress = normalizeAddress(address);
392	        boolean duplicate = this.clinicService.findAllOwners().stream()
393	            .anyMatch(existing -> normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
394	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())));
395	        if (duplicate) {
396	            throw new DuplicateOwnerHouseholdException(lastName, address);
397	        }
398	    }
399	
400	    /**
401	     * Assigns the owner being created a household identifier when the request opts into sharing a
402	     * household. The identifier is a stable value derived from the owner's normalized last name and
403	     * address (see {@link #householdId}), so every owner in the same household is given the exact same
404	     * value regardless of creation order. Any already-existing owner in the same household that has no
405	     * identifier yet is back-filled with the same value so the whole household stays consistent.
406	     *
407	     * @param owner the owner being created, whose household id is set in place
408	     */
409	    private void assignHousehold(Owner owner) {
410	        String householdId = householdId(owner.getLastName(), owner.getAddress());
411	        String normalizedLastName = normalizeForComparison(owner.getLastName());
412	        String normalizedAddress = normalizeAddress(owner.getAddress());
413	        for (Owner existing : this.clinicService.findAllOwners()) {
414	            if (existing.getHouseholdId() == null
415	                && normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
416	                && normalizedAddress.equals(normalizeAddress(existing.getAddress()))) {
417	                existing.setHouseholdId(householdId);
418	                this.clinicService.saveOwner(existing);
419	            }
420	        }
421	        owner.setHouseholdId(householdId);
422	    }
423	
424	    /**
425	     * Derives the stable household identifier for a given last name and address. The value is
426	     * {@code 'HH-' + <12 upper-case hex chars>} of the SHA-256 digest of the normalized last name and
427	     * address (see {@link #normalizeForComparison}), joined by a delimiter. Two owners that resolve to
428	     * the same household therefore always produce the same identifier.
429	     *
430	     * @param lastName the owner's last name
431	     * @param address the owner's address
432	     * @return the stable household identifier
433	     */
434	    private String householdId(String lastName, String address) {
435	        String key = normalizeForComparison(lastName) + "\n" + normalizeAddress(address);
436	        try {
437	            byte[] digest = MessageDigest.getInstance("SHA-256")
438	                .digest(key.getBytes(StandardCharsets.UTF_8));
439	            StringBuilder hex = new StringBuilder();
440	            for (int i = 0; i < 6; i++) {
441	                hex.append(String.format("%02X", digest[i]));
442	            }
443	            return "HH-" + hex;
444	        } catch (NoSuchAlgorithmException ex) {
445	            throw new IllegalStateException("SHA-256 not available", ex);
446	        }
447	    }
448	
449	    /**
450	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and trailing
451	     * whitespace is stripped, every run of internal whitespace is collapsed to a single space, and the
452	     * result is lower-cased. A {@code null} value normalizes to the empty string.
453	     *
454	     * @param value the value to normalize, may be {@code null}
455	     * @return the normalized value
456	     */
457	    private String normalizeForComparison(String value) {
458	        if (value == null) {
459	            return "";
460	        }
461	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
462	    }
463	
464	    /**
465	     * Normalizes an owner address for storage and comparison: leading and trailing whitespace is
466	     * stripped, every run of internal whitespace is collapsed to a single space, the value is
467	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
468	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). For example {@code "  12  main  st "} normalizes to
469	     * {@code "12 MAIN STREET"}. A {@code null} value normalizes to the empty string. This is the form
470	     * that is stored, returned, and used for every address comparison (household duplicate detection
471	     * and the shared household id).
472	     *
473	     * @param address the raw address value from the submitted owner payload, may be {@code null}
474	     * @return the normalized address
475	     */
476	    private String normalizeAddress(String address) {
477	        if (address == null) {
478	            return "";
479	        }
480	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
481	        if (collapsed.isEmpty()) {
482	            return "";
483	        }
484	        String[] tokens = collapsed.split(" ");
485	        StringBuilder normalized = new StringBuilder();
486	        for (int i = 0; i < tokens.length; i++) {
487	            if (i > 0) {
488	                normalized.append(' ');
489	            }
490	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
491	        }
492	        return normalized.toString();
493	    }
494	}
